const el=os.utils.el,esc=os.utils.esc,fmtSize=os.utils.fmtSize;
const bn=p=>String(p).split('/').pop();
const sub=(a,k)=>k===a||k.startsWith(a+'/');

/* ===== SHIM: gira DENTRO l'iframe sandboxed, prima di qualunque script della pagina ===== */
const SHIM=function(init){
  var W=init.w,on=init.mode==='on',MAX=init.max||1000000,M=new Map(),used=0,asked=false;
  var post=function(m){m.hosLS=1;m.w=W;try{parent.postMessage(m,'*')}catch(e){}};
  (init.data||[]).forEach(function(p){M.set(p[0],p[1]);used+=p[0].length+p[1].length});
  var err=function(){
    if(!asked){asked=true;post({t:'req'})}
    return new DOMException("Failed to read the 'localStorage' property from 'Window': The document is sandboxed and lacks the 'allow-same-origin' flag.",'SecurityError');
  };
  var api={
    getItem:function(k){k=String(k);return M.has(k)?M.get(k):null},
    setItem:function(k,v){
      if(arguments.length<2)throw new TypeError("Failed to execute 'setItem' on 'Storage': 2 arguments required, but only "+arguments.length+" present.");
      k=String(k);v=String(v);var o=M.has(k)?M.get(k):null;if(o===v)return;
      var n=used-(o===null?0:k.length+o.length)+k.length+v.length;
      if(n>MAX)throw new DOMException("Failed to execute 'setItem' on 'Storage': Setting the value of '"+k+"' exceeded the quota.",'QuotaExceededError');
      M.set(k,v);used=n;post({t:'set',k:k,v:v});
    },
    removeItem:function(k){k=String(k);if(!M.has(k))return;used-=k.length+M.get(k).length;M["delete"](k);post({t:'del',k:k})},
    clear:function(){if(!M.size)return;M.clear();used=0;post({t:'clear'})},
    key:function(i){var a=Array.from(M.keys());i=Number(i)||0;return i>=0&&i<a.length?a[i]:null}
  };
  var has=function(o,k){return Object.prototype.hasOwnProperty.call(o,k)};
  var target=Object.create(typeof Storage==='function'?Storage.prototype:Object.prototype);
  var ls=new Proxy(target,{
    get:function(t,k){
      if(typeof k==='symbol')return t[k];
      if(k==='length')return M.size;
      if(has(api,k))return api[k];
      if(k in t)return t[k];
      return M.has(k)?M.get(k):undefined;
    },
    set:function(t,k,v){if(typeof k==='symbol')return false;api.setItem(k,v);return true},
    deleteProperty:function(t,k){if(typeof k==='string')api.removeItem(k);return true},
    has:function(t,k){return typeof k==='string'?(M.has(k)||k in t):k in t},
    ownKeys:function(){return Array.from(M.keys())},
    getOwnPropertyDescriptor:function(t,k){
      if(typeof k==='string'&&M.has(k))return{value:M.get(k),writable:true,enumerable:true,configurable:true};
      return undefined;
    }
  });
  var def=function(){Object.defineProperty(window,'localStorage',{configurable:true,enumerable:true,get:function(){if(!on)throw err();return ls}})};
  try{def()}catch(e1){try{delete window.localStorage;def()}catch(e2){post({t:'fail'})}}
  var fire=function(k,o,n){
    try{
      var ev=new StorageEvent('storage',{key:k,oldValue:o,newValue:n,url:String(location.href)});
      try{Object.defineProperty(ev,'storageArea',{value:ls})}catch(x){}
      dispatchEvent(ev);
    }catch(x){}
  };
  addEventListener('message',function(e){
    var m=e.data;if(!m||m.hosLS!==1||m.w!==W)return;
    if(e.source&&e.source!==parent)return;
    e.stopImmediatePropagation();
    if(m.t==='lock'){on=false;return}
    if(m.t!=='sync'||!on)return;
    var k=m.k,o;
    if(k===null){if(!M.size)return;M.clear();used=0;fire(null,null,null);return}
    o=M.has(k)?M.get(k):null;
    if(m.v===null){if(o===null)return;used-=k.length+o.length;M["delete"](k)}
    else{if(o===m.v)return;used+=k.length+m.v.length-(o===null?0:k.length+o.length);M.set(k,m.v)}
    fire(k,o,m.v);
  },true);
};

/* ===== stato persistente (in /Apps/<id>/ : registro.json e dati/<id>.json) ===== */
let REG=[];
try{const j=JSON.parse(os.fs.read('registro.json'));if(Array.isArray(j))REG=j.filter(r=>r&&typeof r.id==='string'&&typeof r.p==='string').map(r=>({id:r.id,p:r.p,on:r.on!==false,t:+r.t||Date.now()}))}catch(e){}
const saveReg=()=>{try{os.fs.write('registro.json',JSON.stringify(REG))}catch(e){os.log('registro non salvato: '+e.message)}};
const find=p=>REG.find(r=>r.p===p);
const DATA={},SZ={};
const data=id=>{
  if(!DATA[id]){const m=new Map();let n=0;
    try{const o=JSON.parse(os.fs.read('dati/'+id+'.json'));if(o&&typeof o==='object')Object.keys(o).forEach(k=>{if(typeof o[k]==='string'){m.set(k,o[k]);n+=k.length+o[k].length}})}catch(e){}
    DATA[id]=m;SZ[id]=n}
  return DATA[id]};
const dirty=new Set();let tm=0,full=0;
const flush=()=>{clearTimeout(tm);tm=0;
  dirty.forEach(id=>{if(!REG.some(r=>r.id===id))return;
    try{os.fs.write('dati/'+id+'.json',JSON.stringify(Object.fromEntries(data(id))))}catch(e){if(!full++)os.notify('localStorage','Impossibile salvare i dati di un file.')}});
  dirty.clear()};
const touch=id=>{dirty.add(id);if(!tm)tm=setTimeout(flush,150)};
const lim=()=>Math.max(1000,+config.maxChars||1000000);

/* ===== finestre aperte ===== */
const WINS={};
const rnd=()=>{const a=new Uint8Array(16);try{crypto.getRandomValues(a)}catch(e){for(let i=0;i<16;i++)a[i]=Math.random()*256}return Array.from(a,x=>x.toString(16).padStart(2,'0')).join('')};
const send=(rec,m)=>{try{m.hosLS=1;m.w=rec.wid;rec.f.contentWindow.postMessage(m,'*')}catch(e){}};
const active=rec=>rec.rid&&REG.find(r=>r.id===rec.rid&&r.on);
const fan=(src,m)=>Object.values(WINS).forEach(x=>{if(x!==src&&x.rid&&x.rid===src.rid)send(x,Object.assign({t:'sync'},m))});
const lockWins=id=>Object.values(WINS).forEach(x=>{if(x.rid===id){x.rid=null;send(x,{t:'lock'})}});
const build=rec=>{
  const R=active(rec);
  const init=R?{w:rec.wid,mode:'on',max:lim(),data:Array.from(data(R.id))}:{w:rec.wid,mode:'off'};
  const tag='<script>('+String(SHIM)+')('+JSON.stringify(init).replace(/</g,'\\u003c')+')<\/script>';
  const h=rec.html;
  for(const re of[/<head(?=[\s>])[^>]*>/i,/<html(?=[\s>])[^>]*>/i,/<!doctype[^>]*>/i]){
    const m=re.exec(h);if(m){const i=m.index+m[0].length;return h.slice(0,i)+tag+h.slice(i)}}
  return tag+h};

/* ===== autorizzazione ===== */
const asks={};
const ask=p=>asks[p]||(asks[p]=Promise.resolve(os.ui.confirm(
  'Il file «'+bn(p)+'» ('+p+') vuole usare il localStorage per salvare dati in modo permanente.\n\nI dati restano su questo dispositivo, separati da quelli degli altri file. Puoi disattivare l’autorizzazione in Impostazioni › localStorage.\n\nConsentire?',
  'Autorizzazione localStorage')).then(v=>{delete asks[p];return !!v},()=>{delete asks[p];return false}));
const grant=p=>{let r=find(p);if(!r){let id;do{id=Math.random().toString(36).slice(2,10)}while(REG.some(x=>x.id===id));r={id,p,on:true,t:Date.now()};REG.push(r)}else r.on=true;saveReg();return r};
const reload=(rec,r)=>{rec.rid=r.id;rec.f.srcdoc=build(rec)};
async function request(rec){          /* la pagina ha toccato localStorage senza autorizzazione */
  if(rec.denied||rec.dead)return;
  const r=find(rec.path);
  if(r&&r.on){if(rec.rid!==r.id)reload(rec,r);return}
  if(r){if(!rec.warned++)os.notify('localStorage disattivato','«'+bn(rec.path)+'» ha provato a usarlo. Riattivalo in Impostazioni › localStorage.');return}
  const ok=await ask(rec.path);
  if(rec.dead)return;
  if(ok)reload(rec,grant(rec.path));else rec.denied=true;
}
const onMsg=e=>{
  const m=e.data;if(!m||m.hosLS!==1||typeof m.w!=='string')return;
  const rec=WINS[m.w];if(!rec)return;
  if(e.source&&rec.f.contentWindow&&e.source!==rec.f.contentWindow)return;
  if(m.t==='req')return request(rec);
  if(m.t==='fail')return os.notify('localStorage','Questo browser non consente di sostituire localStorage in «'+bn(rec.path)+'».');
  const R=active(rec);if(!R)return;
  const d=data(R.id);
  if(m.t==='set'){
    if(typeof m.k!=='string'||typeof m.v!=='string')return;
    const o=d.get(m.k),n=SZ[R.id]-(o===undefined?0:m.k.length+o.length)+m.k.length+m.v.length;
    if(n>lim()){if(!rec.full++)os.notify('localStorage','«'+bn(rec.path)+'» ha superato il limite di spazio: scrittura ignorata.');return}
    d.set(m.k,m.v);SZ[R.id]=n;touch(R.id);fan(rec,{k:m.k,v:m.v});
  }else if(m.t==='del'){
    if(typeof m.k!=='string'||!d.has(m.k))return;
    SZ[R.id]-=m.k.length+d.get(m.k).length;d["delete"](m.k);touch(R.id);fan(rec,{k:m.k,v:null});
  }else if(m.t==='clear'){
    d.clear();SZ[R.id]=0;touch(R.id);fan(rec,{k:null,v:null});
  }
};
addEventListener('message',onMsg);
const onHide=()=>{flush();try{kernel&&kernel.fs.flush()}catch(e){}};
const onVis=()=>{if(document.visibilityState==='hidden')onHide()};
addEventListener('beforeunload',onHide);document.addEventListener('visibilitychange',onVis);

/* ===== apertura dei file .html / .htm ===== */
os.files.handler({ext:['html','htm'],open(path){
  return os.ui.window({title:bn(path),icon:'🌐',w:760,h:520,render(b,win){
    const html=os.fs.read(path);
    const f=document.createElement('iframe');
    f.setAttribute('sandbox','allow-scripts allow-forms allow-modals allow-popups');
    f.style.cssText='width:100%;height:100%;border:0;background:#fff';
    const rec={wid:rnd(),f,path,html,rid:null,denied:false,warned:0,full:0,dead:false};
    WINS[rec.wid]=rec;
    win.onclose.push(()=>{rec.dead=true;delete WINS[rec.wid];flush()});
    b.append(f);
    const r=find(path);
    if(r&&r.on)rec.rid=r.id;
    if(!r&&/localStorage/.test(html)){        /* il file ne parla: chiedi prima di avviarlo */
      ask(path).then(ok=>{if(rec.dead)return;if(ok)rec.rid=grant(path).id;else rec.denied=true;f.srcdoc=build(rec)});
    }else f.srcdoc=build(rec);
  }});
}});

/* ===== segue rinomina / spostamento / eliminazione (serve il permesso «system»; senza, resta tutto il resto) ===== */
let kernel=null;
try{kernel=os.system.kernel}catch(e){os.log('Senza il permesso «system» rinominare, spostare o eliminare un file non aggiorna le autorizzazioni.')}
const forget=r=>{lockWins(r.id);REG.splice(REG.indexOf(r),1);delete DATA[r.id];delete SZ[r.id];dirty.delete(r.id);try{os.fs.rm('dati/'+r.id+'.json')}catch(e){}};
if(kernel){
  os.system.patch(kernel.fs,'mv',orig=>function(a,b){
    const A=kernel.fs.norm(a),B=kernel.fs.norm(b),res=orig.apply(this,arguments);
    const mv=REG.filter(r=>sub(A,r.p));
    if(mv.length){
      const to=r=>B+r.p.slice(A.length);
      const hit=new Set(mv.map(to));
      REG.filter(r=>!mv.includes(r)&&hit.has(r.p)).forEach(forget);   /* destinazione sovrascritta */
      mv.forEach(r=>{const old=r.p;r.p=to(r);Object.values(WINS).forEach(x=>{if(x.path===old)x.path=r.p})});
      saveReg();
    }
    return res});
  os.system.patch(kernel.fs,'rm',orig=>function(a){
    const A=kernel.fs.norm(a),res=orig.apply(this,arguments);
    const gone=REG.filter(r=>sub(A,r.p));
    if(gone.length){gone.forEach(forget);saveReg()}
    return res});
}

/* ===== Impostazioni › localStorage ===== */
os.settings.page({id:'ls',title:'localStorage',icon:'🗄️',render(pg,go){
  const again=()=>go(os.id+'.ls');
  pg.append(el('p','','Gli HTML aperti da Esplora file girano isolati e di norma non possono usare <code>localStorage</code>. Qui vedi i file a cui hai dato il permesso: ognuno ha uno spazio dati proprio. Disattivando un file lo spazio resta salvato ma la pagina non può più usarlo (le finestre già aperte si bloccano subito; dopo una riattivazione riapri il file).'));
  if(!REG.length)pg.append(el('p','','<i>Nessun file ha ancora chiesto di usare localStorage.</i>'));
  REG.slice().sort((a,b)=>bn(a.p).localeCompare(bn(b.p),'it')).forEach(r=>{
    const ex=os.fs.exists(r.p),row=el('div','row');
    row.append(el('span','','<b>'+esc(bn(r.p))+'</b>'+(ex?'':' <span class="chip w">file non trovato</span>')+'<br><small style="color:var(--dim)">'+esc(r.p)+'<br>'+fmtSize(data(r.id)?SZ[r.id]:0)+' di dati · concesso il '+new Date(r.t).toLocaleDateString('it-IT')+'</small>'));
    const c=el('span','ctl');c.style.cssText='display:flex;gap:6px;align-items:center';
    const cb=el('input','sw');cb.type='checkbox';cb.checked=r.on;cb.title='Consenti localStorage a questo file';
    cb.onchange=()=>{r.on=cb.checked;if(!r.on)lockWins(r.id);saveReg();again()};
    const b1=el('button','b','Svuota'),b2=el('button','b','Dimentica');
    b1.onclick=async()=>{if(!await os.ui.confirm('Cancellare tutti i dati salvati da «'+bn(r.p)+'»?'))return;
      data(r.id).clear();SZ[r.id]=0;touch(r.id);flush();
      Object.values(WINS).forEach(x=>{if(x.rid===r.id)send(x,{t:'sync',k:null,v:null})});again()};
    b2.onclick=async()=>{if(!await os.ui.confirm('Revocare l’autorizzazione e cancellare i dati di «'+bn(r.p)+'»?'))return;forget(r);saveReg();again()};
    c.append(b1,b2,cb);row.append(c);pg.append(row)});
}});

return{stop(){
  removeEventListener('message',onMsg);removeEventListener('beforeunload',onHide);document.removeEventListener('visibilitychange',onVis);
  flush();Object.values(WINS).forEach(x=>{x.dead=true});
}};
